public class InnerWorkGroupMonitoringConfigurationFactory(Action<Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration>
{

    internal InnerWorkGroupS3LoggingConfigurationFactory S3LoggingConfigurationFactory { get; set; }

    internal InnerWorkGroupManagedLoggingConfigurationFactory ManagedLoggingConfigurationFactory { get; set; }

    internal InnerWorkGroupCloudWatchLoggingConfigurationFactory CloudWatchLoggingConfigurationFactory { get; set; }

    protected override Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration Create()
    {
        var monitoringConfigurationResult = CreateMonitoringConfiguration();
        factoryAction?.Invoke(monitoringConfigurationResult);

        return monitoringConfigurationResult;
    }

    private Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration CreateMonitoringConfiguration()
    {
        var monitoringConfigurationResult = new Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration();

        return monitoringConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Athena.WorkGroupTypes.MonitoringConfiguration result)
    {
        base.CreateChildren(result);

        result.S3LoggingConfiguration ??= S3LoggingConfigurationFactory?.Build();
        result.ManagedLoggingConfiguration ??= ManagedLoggingConfigurationFactory?.Build();
        result.CloudWatchLoggingConfiguration ??= CloudWatchLoggingConfigurationFactory?.Build();
    }

} // End Of Class

